  ('cc53c7cc-30d0-40b2-bc77-36c6c74e9fe2'::uuid, 'Nice find, and a good reminder that the global standard question deserves more attention than it gets. Is the code or the exact configuration available so we can reproduce the global standard results?', NULL::uuid, '2026-10-13T04:12:02.127571+00:00'::timestamptz::timestamptz),
