  ('0b2c29a0-7663-4b85-9c3f-6a2125765df3'::uuid, 'Appreciate you sharing this with the group. The social context of fintech adoption is largely absent here, and I think it changes how we should read the findings.', NULL::uuid, '2026-08-10T12:29:02.127571+00:00'::timestamptz::timestamptz),
