  ('93e37d92-0e03-4d7a-98a3-bec9880090f5'::uuid, 'I tried reproducing a small part of this and had mixed results. This connects to the work on digital humanities, which tackles a similar trade-off from a different direction.', NULL::uuid, '2026-10-11T21:17:02.127571+00:00'::timestamptz::timestamptz),
