  ('4bbc4c9e-f246-4edd-9451-494d2fd0b7c7'::uuid, 'Appreciate you sharing this with the group. We reproduced part of this for artificial intelligence regulation and the trend held, although the absolute numbers were lower. Which metric did you prioritise, and does the ranking change if you pick another one?', NULL::uuid, '2026-07-22T14:26:02.127571+00:00'::timestamptz::timestamptz),
  ('3c9bb8b8-b1d7-4389-8e30-84a78a144fa4'::uuid, 'Worth a closer look when we plan the next bioinformatics project.', NULL::uuid, '2026-11-04T23:10:02.127571+00:00'::timestamptz::timestamptz),
  ('a3d9386d-0e2e-4dc7-9424-5391dc355f85'::uuid, 'Appreciate you sharing this with the group. For context, the public policy literature has been debating a very similar question for some time.', NULL::uuid, '2026-11-04T02:08:02.127571+00:00'::timestamptz::timestamptz),
