  ('9631a2ea-552e-4364-8e77-b08459d23356'::uuid, 'Ishita, this is the kind of detail that rarely makes it into the paper. There is a useful parallel with signal processing, where the role of DATA MINING METHODS is comparable.', '2d376162-c68b-483a-991c-c2eb09391d3d'::uuid, '2026-09-19T08:28:02.127571+00:00'::timestamptz::timestamptz),
