  ('9b51e991-5ee6-4b82-bc57-34aebfa28b5d'::uuid, 'Thanks for bringing this up; “A beginner’s guide to bioinformatics” is a useful lens on bioinformatics.', NULL::uuid, '2026-10-04T07:22:02.127571+00:00'::timestamptz::timestamptz),
